CREATE TABLE "HealthPharmacyLawyer" (id TEXT PRIMARY KEY,"personId" TEXT NOT NULL UNIQUE REFERENCES "Person"(id) ON DELETE RESTRICT ON UPDATE CASCADE,registration TEXT NOT NULL,"registrationState" TEXT NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(registration,"registrationState"));
CREATE TABLE "HealthPharmacyJudicialCase" (id TEXT PRIMARY KEY,"caseNumber" TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,"patientId" TEXT NOT NULL REFERENCES "Patient"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"unitId" TEXT NOT NULL,"lawyerId" TEXT NOT NULL REFERENCES "HealthPharmacyLawyer"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"openedAt" TIMESTAMP(3) NOT NULL,"validUntil" TIMESTAMP(3) NOT NULL,reason TEXT NOT NULL,"processId" TEXT,"purchaseRequestId" TEXT,status TEXT NOT NULL DEFAULT 'OPEN',"renewalOfId" TEXT REFERENCES "HealthPharmacyJudicialCase"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"createdByUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("caseNumber",version));
CREATE INDEX "HealthPharmacyJudicialCase_patientId_status_idx" ON "HealthPharmacyJudicialCase"("patientId",status);
CREATE INDEX "HealthPharmacyJudicialCase_unitId_status_idx" ON "HealthPharmacyJudicialCase"("unitId",status);
CREATE TABLE "HealthPharmacyJudicialItem" (id TEXT PRIMARY KEY,"caseId" TEXT NOT NULL REFERENCES "HealthPharmacyJudicialCase"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"medicineId" TEXT NOT NULL,quantity DOUBLE PRECISION NOT NULL,dosage TEXT NOT NULL,"prescriptionItemId" TEXT,UNIQUE("caseId","medicineId"));
CREATE TABLE "HealthPharmacyJudicialEvent" (id TEXT PRIMARY KEY,"caseId" TEXT NOT NULL REFERENCES "HealthPharmacyJudicialCase"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"fromStatus" TEXT,"toStatus" TEXT NOT NULL,reason TEXT NOT NULL,"actorUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "HealthPharmacyJudicialDocument" (id TEXT PRIMARY KEY,"caseId" TEXT NOT NULL REFERENCES "HealthPharmacyJudicialCase"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"documentId" TEXT NOT NULL,"actorUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("caseId","documentId"));
ALTER TABLE "MedicineDispensation" ADD COLUMN "judicialCaseItemId" TEXT REFERENCES "HealthPharmacyJudicialItem"(id) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "HealthPharmacyJudicialCase" ADD FOREIGN KEY ("processId") REFERENCES "Process"(id) ON DELETE RESTRICT ON UPDATE CASCADE, ADD FOREIGN KEY ("purchaseRequestId") REFERENCES "PurchaseRequest"(id) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "HealthPharmacyJudicialItem" ADD FOREIGN KEY ("medicineId") REFERENCES "Medicine"(id) ON DELETE RESTRICT ON UPDATE CASCADE, ADD FOREIGN KEY ("prescriptionItemId") REFERENCES "HealthPrescriptionItem"(id) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "HealthPharmacyJudicialDocument" ADD FOREIGN KEY ("documentId") REFERENCES "Document"(id) ON DELETE RESTRICT ON UPDATE CASCADE;
